  singleton_id, brand_name, brand_tagline, hero_headline, hero_subheadline,
  primary_cta_label, secondary_cta_label, contact_email, contact_phone,
  whatsapp_url, support_url, logo_path, hero_image_path, footer_description,
  footer_copyright, canonical_url, meta_title, meta_description, og_image_path,
  social_links, is_published
) values (
  1, 'NEXORA SALONOS',
  'Salon management software for salons, spas and beauty businesses',
  'Run Your Salon. Grow Your Business. All From One Place.',
  'Nexora SalonOS brings appointments, customers, staff, billing, marketing and business insights together in one easy-to-manage platform.',
  'Get Started', 'Explore Features',
  null, null, null, null, null, null,
  'Nexora SalonOS brings appointments, customers, staff, billing, marketing and business reporting into one connected platform for beauty and wellness businesses.',
  '© 2026 Nexora SalonOS. All rights reserved.',
  'https://nexorasalon.online/salon-os',
  'NEXORA SALONOS | Salon Management Software for Salons, Spas & Beauty Businesses', 'Nexora SalonOS brings appointments, customers, staff, billing, marketing and business reports into one connected platform for salons, spas, nail studios and beauty businesses in India.', '/nexora-homepage-og.jpg',
  '{}'::jsonb, true
)
