  primary_cta_label=excluded.primary_cta_label, secondary_cta_label=excluded.secondary_cta_label,
  footer_description=excluded.footer_description, footer_copyright=excluded.footer_copyright,
  canonical_url=excluded.canonical_url, meta_title=excluded.meta_title,
  meta_description=excluded.meta_description, og_image_path=excluded.og_image_path,
