-- landing_sections — section copy and visibility
insert into public.landing_sections (section_key, eyebrow, title, subtitle, body, primary_cta_label, primary_cta_href, secondary_cta_label, secondary_cta_href, content, sort_order, is_published, published_at) values
  ('hero', 'SALON MANAGEMENT SOFTWARE', 'Run Your Salon. Grow Your Business. All From One Place.', 'Nexora SalonOS brings appointments, customers, staff, billing, marketing and business insights together in one easy-to-manage platform.', 'Illustrative interface preview — no live salon data is shown.', 'Get Started', '/login?auth=signup', 'Explore Features', '#features', '{"note":"Illustrative interface preview — no live salon data is shown.","primary_href":"/login?auth=signup","secondary_href":"#features"}'::jsonb, 1, true, now()),
  ('trust_strip', null, null, null, null, null, null, null, null, '{"facts":[{"value":"16","label":"salon website templates"},{"value":"8","label":"feature comparison areas"},{"value":"4","label":"annual salon plans"}]}'::jsonb, 2, true, now()),
  ('business_categories', null, 'Built for the Beauty and Wellness Industry', 'Whether you run a single chair or several locations, Nexora SalonOS is shaped around how beauty businesses actually work.', null, null, null, null, null, '{"items":[{"id":"salon","title":"Salons & beauty parlours","description":"Appointments, services, billing and customer records in one workspace.","icon_key":"scissors"},{"id":"barber","title":"Barbershops","description":"Chair-level scheduling, service menus and everyday POS billing.","icon_key":"razor"},{"id":"spa","title":"Spas & wellness centres","description":"Package services, staff schedules and customer history.","icon_key":"flower"},{"id":"nail","title":"Nail studios","description":"Frequent bookings, service add-ons and product stock.","icon_key":"hand"},{"id":"tattoo","title":"Tattoo studios","description":"Consultation-to-session appointments and deposit billing.","icon_key":"pen"},{"id":"clinic","title":"Skin & beauty clinics","description":"Service menus, practitioner allocation and reporting.","icon_key":"heart"},{"id":"multi","title":"Multi-location businesses","description":"Branches, staff access and consolidated reporting.","icon_key":"store"}]}'::jsonb, 3, true, now()),
  ('problem_solution', null, 'Stop Managing Your Salon With Disconnected Tools.', 'Most salons run on notebooks, spreadsheets and personal apps. Nexora SalonOS brings the everyday parts of the job into one connected workspace.', null, null, null, null, null, '{"before":[{"id":"bookings","title":"Appointments tracked manually","description":"Bookings kept in notebooks, personal calendars or scattered chats."},{"id":"customers","title":"Customer information scattered","description":"Contact details, preferences and visit history spread across files and phones."},{"id":"staff","title":"Staff schedules are hard to coordinate","description":"Ch availability, working hours and leave are worked out by hand."},{"id":"billing","title":"Billing and expenses tracked separately","description":"Daily sales, product costs and expenses never meet in one view."},{"id":"marketing","title":"Marketing handled manually","description":"Every offer, reminder and promotion is prepared from scratch."},{"id":"visibility","title":"No clear business performance overview","description":"Owners cannot see how the salon is actually performing."}],"with_nexora":[{"id":"bookings","title":"Centralised appointment management","description":"Owner-side booking tools alongside a published salon website."},{"id":"customers","title":"Connected customer records","description":"Profiles, booking history and customer notes in one place."},{"id":"staff","title":"Better staff coordination","description":"Staff profiles, scheduling and access controls for your team."},{"id":"billing","title":"Billing and business management tools","description":"Owner-side POS, service and product billing with payment records."},{"id":"marketing","title":"Organised marketing workflows","description":"Campaign creatives, customer communication and recall tools."},{"id":"visibility","title":"Useful business reports and insights","description":"Appointment, revenue, staff and inventory reporting where supported."}]}'::jsonb, 4, true, now()),
  ('core_features', null, 'Everything Your Salon Needs to Operate Better.', 'Grouped by the work you do every day, using the tools that are already part of the Nexora SalonOS workspace.', null, null, null, null, null, '{"groups":[{"id":"appointments","title":"Appointment management","benefit":"See the day ahead and keep every slot accounted for.","icon_key":"calendar","feature_ids":["online-booking","availability","booking-management","reminders"]},{"id":"customers","title":"Customer management","benefit":"Know who visited, what they booked and what they prefer.","icon_key":"users","feature_ids":["customer-database","profiles","booking-history","crm","notes","segmentation"]},{"id":"billing","title":"Billing and payments","benefit":"Bill services and products at the counter, with the record kept.","icon_key":"rupee","feature_ids":["pos","service-billing","payments","invoices","expenses","transactions"]},{"id":"staff","title":"Staff management","benefit":"Give the right people the right access, and track their day.","icon_key":"staff","feature_ids":["staff-profiles","staff-access","scheduling","staff-management","attendance","performance"]},{"id":"inventory","title":"Inventory and products","benefit":"Know what is on the shelf before the customer asks for it.","icon_key":"inventory","feature_ids":["catalogue","inventory","stock","alerts","product-sales"]},{"id":"marketing","title":"Marketing and customer growth","benefit":"Prepare campaigns and stay in touch with existing customers.","icon_key":"megaphone","feature_ids":["campaigns","marketing","notifications","follow-up","recall","whatsapp"]},{"id":"analytics","title":"Business analytics","benefit":"Read bookings, revenue and team performance from actual records.","icon_key":"chart","feature_ids":["analytics","booking-reports","revenue-analytics","staff-reports","stock-reports","insights"]},{"id":"presence","title":"Digital salon presence","benefit":"Give customers a real salon website to explore and book from.","icon_key":"globe","feature_ids":["mini-website","business-profile","services","service-pricing","gallery","sharing"]}]}'::jsonb, 5, true, now()),
  ('how_it_works', null, 'Get Started in Three Simple Steps.', 'No parallel system to maintain. Start with the essentials and grow from there.', null, null, null, null, null, '{"steps":[{"id":"account","title":"Create your salon account","description":"Add your salon details and configure your business profile from the start.","icon_key":"store"},{"id":"setup","title":"Set up your services and team","description":"Add services, staff, schedules and the business settings your salon works with.","icon_key":"layers"},{"id":"manage","title":"Manage and grow your business","description":"Use the workspace tools for appointments, customers, operations and marketing.","icon_key":"chart"}]}'::jsonb, 6, true, now()),
  ('pricing', null, 'Choose the Right Plan for Your Salon.', 'Start with the essentials and upgrade as your business grows.', null, null, null, null, null, '{"currency":"INR","billing_intervals":["annual"],"note":"Displayed annual prices include GST. Monthly billing rates and subscription checkout are not configured yet."}'::jsonb, 7, true, now()),
  ('salon_promotion_studio', null, 'Create Your Salon Promotions. Share Them Everywhere.', 'Make professional promotional creatives for your salon without depending on a designer for every small offer.', null, null, null, null, null, '{"workflow":[{"id":"register","title":"Register your salon","description":"Your business details are already in the Nexora workspace.","icon_key":"store"},{"id":"choose","title":"Choose a creative","description":"Pick an approved design that fits the offer you are running.","icon_key":"palette"},{"id":"details","title":"Add your offer details","description":"Salon name, offer, code and booking link are added by you.","icon_key":"type"},{"id":"generate","title":"Generate the creative","description":"The campaign module renders the creative in the format you need.","icon_key":"wand"},{"id":"share","title":"Download and share","description":"Export the creative and publish it on the channels you use.","icon_key":"share"}],"channels":[{"id":"whatsapp-status","label":"WhatsApp Status","status":"available","note":"Download the creative and post it to your status."},{"id":"whatsapp-groups","label":"WhatsApp groups","status":"available","note":"Share with customer groups you already manage."},{"id":"instagram-post","label":"Instagram posts","status":"available","note":"Square and portrait formats are supported."},{"id":"instagram-story","label":"Instagram stories","status":"available","note":"9:16 and 16:9 formats are supported."},{"id":"facebook-page","label":"Facebook page","status":"planned","note":"Direct publishing is not connected yet."},{"id":"google-business","label":"Google Business Profile","status":"planned","note":"Posting integration is not connected yet."},{"id":"telegram","label":"Telegram","status":"planned","note":"Direct publishing is not connected yet."},{"id":"qr","label":"Printable QR poster","status":"planned","note":"QR creative generation is not connected yet."}]}'::jsonb, 8, true, now()),
  ('business_benefits', null, 'More Control Over Your Daily Salon Operations.', 'One Connected Place for Your Salon Operations.', null, null, null, null, null, '{"benefits":[{"id":"appointments","title":"Manage appointments","description":"Bookings, availability and appointment status stay in one owner-side view.","icon_key":"calendar"},{"id":"customers","title":"Understand your customers","description":"Customer profiles, visit history and notes are available when you need them.","icon_key":"users"},{"id":"team","title":"Coordinate your team","description":"Give staff the access they need and keep schedules and roles clear.","icon_key":"staff"},{"id":"tracking","title":"Track business activity","description":"Read appointment, revenue, staff and inventory reports from real records.","icon_key":"chart"},{"id":"products","title":"Organise your products","description":"Catalogue products, watch stock levels and record what was consumed.","icon_key":"inventory"},{"id":"promote","title":"Promote your salon","description":"Prepare campaign creatives for the offers you want to run next.","icon_key":"megaphone"}]}'::jsonb, 9, true, now()),
  ('product_preview', null, 'A Clear View of Your Salon Business.', 'An illustrative look at the workspace areas a salon team uses every day.', null, null, null, null, null, '{"note":"Illustrative interface preview — no live salon data is shown.","areas":["Appointments","Customers","Billing","Staff","Inventory","Reports"]}'::jsonb, 10, true, now()),
  ('testimonials', null, 'Built Around Real Salon Business Needs.', null, null, null, null, null, null, '{"note":"No customer testimonial has been approved for publication yet, so this section states the product position instead of showing quotes."}'::jsonb, 11, true, now()),
  ('faq', null, 'Frequently Asked Questions', null, null, null, null, null, null, '{"source":"public.faqs"}'::jsonb, 12, true, now()),
  ('final_cta', null, 'Ready to Manage Your Salon More Simply?', 'Bring your appointments, customers, team and business operations into one connected platform.', null, 'Get Started', '/login?auth=signup', 'View pricing', '/pricing', '{"disclosures":["No independently verified revenue-uplift, ranking or customer-count claim is made on this page.","No refund guarantee, free-trial promise or money-back term is offered on this page.","Plan entitlements are shown only where they have been confirmed; everything else is marked as pending.","Displayed annual prices include GST. Monthly billing rates and subscription checkout are not configured yet."]}'::jsonb, 13, true, now())
on conflict (section_key) do update set
  eyebrow=excluded.eyebrow, title=excluded.title, subtitle=excluded.subtitle, body=excluded.body,
