  secondary_cta_label=excluded.secondary_cta_label, secondary_cta_href=excluded.secondary_cta_href,
  content=excluded.content, sort_order=excluded.sort_order, is_published=excluded.is_published,
  published_at=excluded.published_at, updated_at=now();

