    ('header', 'Features', '#features', false, 2),
    ('mobile', 'Features', '#features', false, 2),
    ('header', 'Solutions', '#solutions', false, 3),
    ('mobile', 'Solutions', '#solutions', false, 3),
    ('header', 'Pricing', '#pricing', false, 4),
    ('mobile', 'Pricing', '#pricing', false, 4),
    ('header', 'Salon Marketing', '#salon-marketing', false, 5),
    ('mobile', 'Salon Marketing', '#salon-marketing', false, 5),
    ('header', 'Resources', '#faq', false, 6),
    ('mobile', 'Resources', '#faq', false, 6),
    ('footer', 'Features', '#features', false, 1),
    ('footer', 'How it works', '#how-it-works', false, 2),
    ('footer', 'Salon solutions', '#solutions', false, 3),
    ('footer', 'Pricing', '#pricing', false, 4),
    ('footer', 'Compare plans', '#comparison', false, 5),
    ('footer', 'Promotion studio', '#salon-marketing', false, 101),
    ('footer', 'Creative gallery', '#salon-marketing', false, 102),
    ('footer', 'Marketing campaigns', '/?app=1&module=22', true, 103),
    ('footer', 'Product preview', '#product-preview', false, 201),
    ('footer', 'Business benefits', '#benefits', false, 202),
    ('footer', 'FAQs', '#faq', false, 203),
    ('footer', 'Salon templates', '/', true, 204),
