-- pricing_plans — approved annual pricing; the monthly rate is not configured
insert into public.pricing_plans (plan_key, name, tagline, description, price_monthly, price_yearly, currency, monthly_billing_label, yearly_billing_label, yearly_discount_label, cta_label, cta_href, is_recommended, display_order, is_active, is_published) values
  ('lite', 'Lite', 'For independent beauty professionals who need an organized way to manage their everyday salon business.', 'Great for Solopreneurs and Just Getting Started.', null, 7500.00, 'INR', null, 'Per year (incl. GST)', null, 'Get Started', '/login?auth=signup', false, 1, true, true),
  ('grow', 'Grow', 'For salons that want better customer management, booking control and business visibility.', 'Great for small businesses with steady bookings.', null, 14988.00, 'INR', null, 'Per year (incl. GST)', null, 'Choose Grow', '/login?auth=signup', false, 2, true, true),
  ('standard', 'Standard', 'For growing teams looking for more connected day-to-day salon operations.', 'Growing businesses with automation, reminders & insights.', null, 23988.00, 'INR', null, 'Per year (incl. GST)', null, 'Choose Standard', '/login?auth=signup', true, 3, true, true),
  ('premium', 'Premium', 'For established salons and larger beauty businesses requiring comprehensive management and advanced operational controls.', 'For high-traffic businesses needing full control.', null, 59988.00, 'INR', null, 'Per year (incl. GST)', null, 'Contact Sales', '/salon-os#final-cta', false, 4, true, true)
on conflict (plan_key) do update set
