  price_monthly=excluded.price_monthly, price_yearly=excluded.price_yearly,
  yearly_billing_label=excluded.yearly_billing_label, cta_label=excluded.cta_label,
  cta_href=excluded.cta_href, is_recommended=excluded.is_recommended,
  display_order=excluded.display_order, is_active=excluded.is_active,
  is_published=excluded.is_published, updated_at=now();

-- plan_features — only the three confirmed Standard inclusions; every other
-- tier assignment stays absent until it is commercially confirmed
insert into public.plan_features (plan_id, feature_id, availability, quantity_limit, limit_unit, display_value, notes, sort_order)
select pp.id, f.id, 'included', null, null, 'Included',
  'Confirmed in the approved Standard plan inputs.', 0
from public.pricing_plans pp join public.features f on f.slug in (
  'attendance', 'whatsapp-api', 'advanced-salon-management')
where pp.plan_key = 'standard'
on conflict (plan_id, feature_id) do update set
  availability=excluded.availability, display_value=excluded.display_value,
  notes=excluded.notes, updated_at=now();

-- promotional_creatives — DRAFT rows. Upload the image objects to the
-- nexora-public-assets bucket before setting is_published = true.
insert into public.promotional_creatives (title, category, description, image_path, image_alt, cta_label, cta_href, share_targets, display_order, is_published)
select v.title, v.category, v.description, v.image_path, v.image_alt, v.cta_label, v.cta_href, v.share_targets, v.ord, false
from (values
    ('Signature Haircut Week', 'Hair & styling', 'SPECIAL PRICE · Cut, wash & finish · Mon to Sat', 'promotions/haircut-offer.webp', 'Signature Haircut Week — Cut, wash & finish · Mon to Sat (illustrative Nexora sample creative)', 'Learn more', '/salon-os#final-cta', array['whatsapp_status', 'whatsapp_groups', 'instagram_post', 'instagram_story'], 1),
    ('Bridal Glow Package', 'Bridal & occasion', 'BRIDAL PACKAGE · Trial session included', 'promotions/bridal-offer.webp', 'Bridal Glow Package — Trial session included (illustrative Nexora sample creative)', 'Learn more', '/salon-os#final-cta', array['whatsapp_status', 'whatsapp_groups', 'instagram_post', 'instagram_story'], 2),
    ('Festive Glow Offer', 'Festival offers', 'FESTIVE SPECIAL · Limited slots this week', 'promotions/festival-offer.webp', 'Festive Glow Offer — Limited slots this week (illustrative Nexora sample creative)', 'Learn more', '/salon-os#final-cta', array['whatsapp_status', 'whatsapp_groups', 'instagram_post', 'instagram_story'], 3),
    ('Spa Reset Session', 'Spa & wellness', 'RELAX & REFRESH · 60 min full body ritual', 'promotions/spa-offer.webp', 'Spa Reset Session — 60 min full body ritual (illustrative Nexora sample creative)', 'Learn more', '/salon-os#final-cta', array['whatsapp_status', 'whatsapp_groups', 'instagram_post', 'instagram_story'], 4),
    ('Gel Nail Art Session', 'Nail studio', 'NAIL ART SESSION · Includes maintenance', 'promotions/nail-offer.webp', 'Gel Nail Art Session — Includes maintenance (illustrative Nexora sample creative)', 'Learn more', '/salon-os#final-cta', array['whatsapp_status', 'whatsapp_groups', 'instagram_post', 'instagram_story'], 5),
    ('Custom Ink Session', 'Tattoo studio', 'CUSTOM INK SESSION · Design consultation included', 'promotions/tattoo-offer.webp', 'Custom Ink Session — Design consultation included (illustrative Nexora sample creative)', 'Learn more', '/salon-os#final-cta', array['whatsapp_status', 'whatsapp_groups', 'instagram_post', 'instagram_story'], 6),
