-- faqs — published answers that already match the live page
insert into public.faqs (category, question, answer, sort_order, is_published)
select v.category, v.question, v.answer, v.ord, true
from (values
    ('Product', 'What is Nexora SalonOS?', 'Nexora SalonOS is a connected platform for beauty and wellness businesses. It brings a published salon website together with owner-side tools for services, staff, customers, appointments, billing, campaigns and business reporting, so a salon can run from one workspace instead of several disconnected tools.', 1),
    ('Product', 'Which types of businesses can use it?', 'Nexora SalonOS is designed for salons and beauty parlours, barbershops, spas and wellness centres, nail studios, tattoo studios, skin and beauty clinics, and multi-location salon businesses. You choose the business type and template when you set up your workspace.', 2),
    ('Getting started', 'How can I get started?', 'Create a Nexora account from the Get Started button on this page, add your salon details, then configure your services, staff and business settings. Publishing your salon website and sharing its booking link is part of the same workspace.', 3),
    ('Pricing', 'What features are included in each plan?', 'Only plan inclusions that have been explicitly confirmed are marked in the comparison table. Standard explicitly includes WhatsApp API, attendance and advanced salon management. Other feature-by-plan assignments are still under commercial review, and the table marks them as pending rather than guessing. Displayed annual prices include GST.', 4),
    ('Pricing', 'Can I change my subscription plan?', 'Subscription plan changes are not handled by a configured billing workflow at the moment. Please confirm plan-change terms with Nexora before you purchase, and choose the plan that matches how you run your salon today.', 5),
    ('Plans and limits', 'Can I manage multiple staff members?', 'Yes. The workspace includes staff profiles, staff access, scheduling and staff management tools. The number of staff seats included in each subscription tier has not been configured, so confirm the limit that applies to you before you subscribe.', 6),
    ('Bookings', 'Does Nexora support online bookings?', 'Yes. Customers can request appointments through your published salon website, and the owner side includes appointment and booking management tools. Plan availability for online booking is still being confirmed, so check the comparison table before you purchase.', 7),
    ('Billing and inventory', 'Can I manage products and billing?', 'The application includes owner-side point-of-sale billing, service billing, payment tracking, invoices and expense records, plus a product catalogue with inventory tracking and stock alerts. Which of these are included in each plan is still being confirmed.', 8),
    ('Marketing', 'Does Nexora support salon marketing?', 'Yes. The Marketing campaigns module builds promotion creatives from your services, offer, promo code and booking link, and exports them for the formats used on social channels. Customer communication, recall and loyalty tools are also part of the workspace. WhatsApp API is confirmed for the Standard plan only.', 9),
    ('Devices', 'Can I use Nexora on mobile and desktop?', 'Yes. Nexora runs in the browser and works on phones, tablets and desktops, and the salon websites you publish are responsive. For the day-to-day counter work, a larger screen is easier to use, but nothing is locked to a desktop.', 10),
    ('Data and privacy', 'Where is my business data stored?', 'Your workspace data is stored in the Supabase project configured for Nexora, and salon media is stored in Supabase storage. Nexora has not published a specific storage region, so please ask if a data-residency requirement applies to your business.', 11),
    ('Data and privacy', 'How is my data protected?', 'Workspace access is tied to your Nexora account, the application supports role-based access for staff, and database policies restrict what each signed-in user can read or change. Nexora does not publish security certifications on this page, so please request the current documentation if a formal assurance is needed.', 12),
    ('Integrations', 'Are WhatsApp API features included?', 'WhatsApp API is confirmed as included in the Standard plan. The other tiers are still under review. API credentials, message template approval and delivery setup are separate platform configuration, and any messaging charged by your provider applies on top of your Nexora plan.', 13),
    ('Integrations', 'Are third-party integrations included?', 'No third-party integration is included with a Nexora plan today. Add-on capabilities such as WhatsApp API, advanced marketing automation, extra staff seats, extra branches, advanced inventory, advanced analytics, premium website customisation and priority support exist as options, but their rates are not configured and are confirmed directly with Nexora.', 14),
    ('Support', 'How can I contact support?', 'Use the support channel already provided inside your Nexora account. If you are still deciding, the Book a Demo form on this page sends your request through the configured server-side demo integration, and the team can also walk you through plan details. Nexora has not published a support phone number or support email on this page.', 15)
) as v(category, question, answer, ord)
where not exists (select 1 from public.faqs f where f.question = v.question);

